<!doctype html>
<html lang="tr">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="theme-color" content="#06101d">
<title>WAI Insurance OS • Sigorta Acente Otomasyonu</title>
<style>
:root{--bg:#06101d;--panel:#0a1728;--panel2:#10233a;--line:#203752;--text:#f6fbff;--muted:#90a6bd;--blue:#49a8ff;--green:#35d296;--amber:#ffc45c;--red:#ff7070;--shadow:0 24px 80px rgba(0,0,0,.34)}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:Inter,ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:radial-gradient(circle at 12% 0,#153b64 0,transparent 31%),radial-gradient(circle at 95% 8%,#0e4e43 0,transparent 26%),var(--bg);color:var(--text);min-height:100vh}button{font:inherit;cursor:pointer}.wrap{max-width:1200px;margin:auto;padding:24px 16px 54px}.top{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:22px}.brand{display:flex;align-items:center;gap:12px}.logo{width:48px;height:48px;border-radius:15px;display:grid;place-items:center;background:linear-gradient(135deg,#4aa9ff,#23d39b);font-weight:950;font-size:18px;box-shadow:0 14px 36px rgba(73,168,255,.25)}.brand b{font-size:15px}.brand span{display:block;color:var(--muted);font-size:12px;margin-top:3px}.badge{padding:8px 12px;border:1px solid rgba(53,210,150,.35);background:rgba(53,210,150,.08);border-radius:999px;color:#b9f1d9;font-size:11px;font-weight:900;white-space:nowrap}.hero{position:relative;overflow:hidden;border:1px solid rgba(255,255,255,.08);background:linear-gradient(155deg,rgba(15,34,58,.97),rgba(6,16,29,.96));border-radius:30px;padding:38px;box-shadow:var(--shadow)}.hero:after{content:"";position:absolute;width:320px;height:320px;border-radius:50%;background:rgba(73,168,255,.08);right:-120px;top:-130px}.eyebrow{color:#91d0ff;font-size:11px;font-weight:950;letter-spacing:.15em;text-transform:uppercase}.hero h1{font-size:clamp(34px,5.4vw,64px);line-height:1;letter-spacing:-.045em;margin:12px 0;max-width:880px}.hero p{max-width:820px;color:#b8c8d8;font-size:16px;line-height:1.68;margin:0}.hero-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:22px}.primary,.secondary{border-radius:13px;padding:13px 16px;font-weight:900;border:0}.primary{background:linear-gradient(135deg,#2cc487,#258bd7);color:white}.secondary{border:1px solid var(--line);background:#0c1b2d;color:#cfe1f2}.proof{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:18px}.proof .item{border:1px solid rgba(255,255,255,.08);background:rgba(255,255,255,.035);border-radius:15px;padding:14px}.proof b{display:block;font-size:13px}.proof span{display:block;color:var(--muted);font-size:11px;margin-top:4px;line-height:1.4}.tabs{display:flex;gap:8px;margin:22px 0;position:sticky;top:8px;z-index:8;background:rgba(6,16,29,.82);backdrop-filter:blur(14px);padding:7px;border-radius:17px}.tab{flex:1;border:1px solid var(--line);background:#0a1728;color:#99aec4;border-radius:12px;padding:13px 9px;font-weight:900;font-size:12px}.tab.active{background:linear-gradient(135deg,#166bbd,#0d8e77);color:#fff;border-color:transparent}.grid{display:grid;grid-template-columns:1.05fr .95fr;gap:18px}.card{border:1px solid var(--line);background:rgba(10,23,40,.94);border-radius:22px;padding:22px;box-shadow:0 16px 52px rgba(0,0,0,.21)}.card h3{margin:0 0 6px;font-size:18px}.sub{color:var(--muted);font-size:13px;line-height:1.55}.phone{max-width:425px;margin:18px auto 0;background:#050d15;border:1px solid #2b425e;border-radius:34px;padding:10px;box-shadow:0 24px 70px rgba(0,0,0,.44)}.phone-top{height:34px;display:grid;place-items:center}.notch{width:110px;height:19px;border-radius:999px;background:#020508}.screen{background:linear-gradient(180deg,#0e1c2c,#09141f);border-radius:26px;overflow:hidden;min-height:560px}.wa-head{display:flex;align-items:center;gap:10px;padding:14px 15px;border-bottom:1px solid rgba(255,255,255,.06);background:#0c1c2d}.avatar{width:41px;height:41px;border-radius:50%;display:grid;place-items:center;background:linear-gradient(135deg,#4aa9ff,#35d296);font-weight:950}.wa-head b{font-size:14px}.wa-head small{display:block;color:#78dcae;font-size:11px;margin-top:2px}.chat{padding:16px 13px;display:flex;flex-direction:column;gap:9px;min-height:452px}.msg{max-width:86%;padding:11px 12px;border-radius:12px;font-size:13px;line-height:1.45;box-shadow:0 4px 12px rgba(0,0,0,.15)}.incoming{background:#17283a;border-top-left-radius:3px}.outgoing{background:#0d5a4a;align-self:flex-end;border-top-right-radius:3px}.time{display:block;color:#8da1b8;font-size:9px;text-align:right;margin-top:4px}.composer{padding:10px;border-top:1px solid rgba(255,255,255,.06)}.upload{width:100%;border:1px dashed #35608a;background:#10223a;color:#d7e8f7;border-radius:13px;padding:13px;font-weight:900}.steps{display:grid;gap:10px;margin-top:17px}.step{display:flex;gap:11px;align-items:center;padding:12px;border:1px solid var(--line);background:#0a1728;border-radius:13px}.dot{width:29px;height:29px;border-radius:50%;display:grid;place-items:center;background:#142841;color:#7892ad;font-size:11px;font-weight:950;flex:0 0 auto}.step.done .dot{background:rgba(53,210,150,.15);color:#67e8b1}.step.active{border-color:#2e86c4;background:rgba(73,168,255,.07)}.step.active .dot{background:rgba(73,168,255,.17);color:#86cbff}.step strong{font-size:13px;display:block}.step span{font-size:11px;color:var(--muted);display:block;margin-top:2px}.result{display:none;margin-top:15px;border:1px solid rgba(53,210,150,.34);background:linear-gradient(145deg,rgba(53,210,150,.1),rgba(73,168,255,.06));border-radius:17px;padding:17px}.result.show{display:block}.price{font-size:39px;font-weight:950;letter-spacing:-.035em;margin:7px 0}.pay{width:100%;border:0;border-radius:13px;padding:14px;background:linear-gradient(135deg,#27c586,#2089d3);color:white;font-weight:950;margin-top:10px}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:11px;margin:17px 0}.kpi{padding:16px;border:1px solid var(--line);background:#091626;border-radius:15px}.kpi b{font-size:27px;display:block}.kpi span{font-size:11px;color:var(--muted)}.table{border:1px solid var(--line);border-radius:15px;overflow:auto}.row{min-width:780px;display:grid;grid-template-columns:1fr 1.15fr 1.15fr .9fr .8fr;gap:8px;align-items:center;padding:13px;border-bottom:1px solid rgba(255,255,255,.06);font-size:12px}.row:last-child{border-bottom:0}.row.head{background:#091626;color:#8fa6bd;font-weight:900}.status{display:inline-block;padding:7px 9px;border-radius:9px;font-size:10px;font-weight:950}.danger{color:#ffb6b6;background:rgba(255,112,112,.12)}.ok{color:#a7efd1;background:rgba(53,210,150,.1)}.action{border:1px solid #2b557f;background:#102740;color:#b9dcff;border-radius:9px;padding:8px 9px;font-weight:900}.overview{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.overview .box{border:1px solid var(--line);background:#0a1728;border-radius:18px;padding:18px}.overview h4{margin:0 0 7px}.overview p{margin:0;color:var(--muted);font-size:12px;line-height:1.55}.flow{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:16px}.flow span{padding:9px 11px;border:1px solid var(--line);border-radius:10px;background:#0a1728;font-size:11px;font-weight:900;color:#d6e4f0}.flow i{font-style:normal;color:#5cb8ff}.notice{margin-top:17px;padding:13px 15px;border-radius:13px;border:1px solid rgba(255,196,92,.24);background:rgba(255,196,92,.07);color:#e8cb92;font-size:11px;line-height:1.55}.hidden{display:none}.toast{position:fixed;left:50%;bottom:22px;transform:translateX(-50%) translateY(18px);background:#f6fbff;color:#06101d;padding:12px 16px;border-radius:12px;font-size:12px;font-weight:900;opacity:0;pointer-events:none;transition:.25s;z-index:20;box-shadow:0 14px 40px rgba(0,0,0,.3)}.toast.show{opacity:1;transform:translateX(-50%) translateY(0)}@media(max-width:900px){.proof{grid-template-columns:1fr 1fr}.grid{grid-template-columns:1fr}.overview{grid-template-columns:1fr}.kpis{grid-template-columns:1fr 1fr}.hero{padding:27px 21px}.wrap{padding:17px 11px 38px}.top{align-items:flex-start}.brand span{max-width:210px}.badge{font-size:9px}.tab{font-size:11px;padding:12px 7px}.card{padding:16px}}@media(max-width:520px){.proof,.kpis{grid-template-columns:1fr}.hero h1{font-size:39px}.hero-actions{display:grid}.primary,.secondary{width:100%}}
</style>
</head>
<body>
<div class="wrap">
<div class="top"><div class="brand"><div class="logo">W</div><div><b>WAI Insurance OS</b><span>Sigorta Acenteleri İçin Operasyon Otomasyonu</span></div></div><div class="badge">● CANLI DEMO</div></div>
<section class="hero">
<div class="eyebrow">Sigorta acenteleri için yeni nesil operasyon</div>
<h1>Ruhsat geldiği anda işlem başlasın.</h1>
<p>WhatsApp üzerinden gelen ruhsatı tek akışta işleyin, teklif sürecini hızlandırın, ödeme aşamasına daha kısa sürede ulaşın ve başka yerde yenilenen poliçeleri satış ekibiniz için görünür hale getirin.</p>
<div class="hero-actions"><button class="primary" onclick="goDemo()">Demoyu Başlat</button><button class="secondary" onclick="showTab('overview')">Sistemi İncele</button></div>
<div class="proof"><div class="item"><b>WhatsApp odaklı</b><span>Personelin alıştığı kanaldan işlem</span></div><div class="item"><b>Tek akış</b><span>Ruhsattan teklif ve ödeme adımına</span></div><div class="item"><b>Geri kazanım</b><span>Kaçan yenilemeleri satış listesine dönüştürme</span></div><div class="item"><b>Yüksek hacim</b><span>Çoklu kullanıcı ve yoğun operasyon mantığı</span></div></div>
</section>
<div class="tabs"><button class="tab active" data-tab="quote">Ruhsattan Teklif</button><button class="tab" data-tab="monitor">Poliçe Takip</button><button class="tab" data-tab="overview">Nasıl Çalışır?</button></div>
<section id="quoteTab"><div class="grid">
<div class="card"><h3>WhatsApp Personel Akışı</h3><div class="sub">Aşağıdaki “Ruhsat Gönder” butonuna dokunarak örnek süreci çalıştırın.</div><div class="phone"><div class="phone-top"><div class="notch"></div></div><div class="screen"><div class="wa-head"><div class="avatar">AI</div><div><b>WAI Sigorta Operasyon</b><small>● çevrimiçi</small></div></div><div class="chat" id="chat"><div class="msg incoming">Merhaba. Ruhsatı gönderdiğiniz anda araç bilgilerini okuyup teklif sürecini başlatabilirim.<span class="time">09:41</span></div></div><div class="composer"><button class="upload" id="startBtn">＋ Ruhsat Gönder</button></div></div></div></div>
<div class="card"><h3>İşlem Motoru</h3><div class="sub">Personel yalnızca ruhsatı gönderir; kalan adımlar entegrasyon yapısına göre otomatik ilerler.</div><div class="steps"><div class="step" id="s1"><div class="dot">1</div><div><strong>Ruhsat alındı</strong><span>Belge işleme kuyruğuna eklendi</span></div></div><div class="step" id="s2"><div class="dot">2</div><div><strong>Araç bilgileri okunuyor</strong><span>Plaka • motor no • şasi no • marka/model</span></div></div><div class="step" id="s3"><div class="dot">3</div><div><strong>Teklif sistemi sorgusu</strong><span>Yetkili entegrasyon üzerinden</span></div></div><div class="step" id="s4"><div class="dot">4</div><div><strong>Tek prim sonucu</strong><span>Personele tek sonuç olarak sunulur</span></div></div><div class="step" id="s5"><div class="dot">5</div><div><strong>Ödeme / onay</strong><span>İşlem ödeme aşamasına taşınır</span></div></div></div><div class="result" id="result"><div class="sub">34 WAI 286 • Renault Clio • 2023</div><div style="font-size:12px;color:#8eb0cb;margin-top:9px">Trafik Sigortası • Tek Prim</div><div class="price">9.486 TL</div><div style="font-size:12px;color:#85e3ba;font-weight:900">✓ Teklif başarıyla hazırlandı</div><button class="pay" id="payBtn">Ödeme Aşamasına Geç</button></div></div>
</div></section>
<section id="monitorTab" class="hidden"><div class="card"><h3>Poliçe Takip & Satış Geri Kazanım Merkezi</h3><div class="sub">Aktif portföy içinden başka yerde yenilenen veya yeniden temas gerektiren kayıtları satış ekibine görünür hale getiren operasyon ekranı.</div><div class="kpis"><div class="kpi"><b>3.247</b><span>Aktif poliçe</span></div><div class="kpi"><b>142</b><span>Kontrol bekleyen</span></div><div class="kpi"><b>37</b><span>Yeni poliçe tespiti</span></div><div class="kpi"><b>24</b><span>Satış ekibine aktarılan</span></div></div><div class="table"><div class="row head"><div>ARAÇ</div><div>MEVCUT POLİÇE</div><div>SON KONTROL</div><div>DURUM</div><div>İŞLEM</div></div><div class="row"><div><b>34 WAI 286</b><br><span class="sub">Renault Clio</span></div><div>12.10.2025<br><span class="sub">Trafik</span></div><div>07.09.2026 • 18:12</div><div><span class="status danger">Yeni poliçe tespit edildi</span></div><div><button class="action" onclick="assigned(this)">Ekibe aktar</button></div></div><div class="row"><div><b>06 OS 541</b><br><span class="sub">Fiat Egea</span></div><div>22.11.2025<br><span class="sub">Trafik + Kasko</span></div><div>07.09.2026 • 18:09</div><div><span class="status ok">Aktif / sorun yok</span></div><div>—</div></div><div class="row"><div><b>35 AI 774</b><br><span class="sub">Toyota Corolla</span></div><div>04.10.2025<br><span class="sub">Trafik</span></div><div>07.09.2026 • 17:58</div><div><span class="status danger">Geri kazanım fırsatı</span></div><div><button class="action" onclick="assigned(this)">Ekibe aktar</button></div></div></div></div></section>
<section id="overviewTab" class="hidden"><div class="card"><h3>Sistem Nasıl Çalışır?</h3><div class="sub">WAI Insurance OS mevcut çalışma düzeninizi tamamen değiştirmek yerine, WhatsApp ve acente altyapınız arasında hızlandırıcı bir operasyon katmanı olarak konumlanır.</div><div class="overview" style="margin-top:17px"><div class="box"><h4>1. Ruhsatı Al</h4><p>Personel WhatsApp üzerinden ruhsatı gönderir. Sistem gerekli araç bilgilerini otomatik olarak çıkarır.</p></div><div class="box"><h4>2. Teklif Akışını Başlat</h4><p>Veriler mevcut sigorta/acente altyapısına aktarılır ve yetkili entegrasyon üzerinden teklif süreci tetiklenir.</p></div><div class="box"><h4>3. Satışı Hızlandır</h4><p>Tek prim sonucu personele sunulur ve işlem mümkün olduğunca doğrudan ödeme/onay aşamasına taşınır.</p></div><div class="box"><h4>4. Poliçeleri Takip Et</h4><p>Mevcut poliçe portföyü düzenli olarak kontrol edilir ve yeniden satış fırsatları görünür hale getirilir.</p></div><div class="box"><h4>5. Satış Ekibine Aktar</h4><p>Başka yerde yenilenen veya riskli hale gelen müşteri kayıtları geri kazanım listesine alınır.</p></div><div class="box"><h4>6. Yönetici Görünürlüğü</h4><p>İşlem hacmi, bekleyen sorgular ve geri kazanım fırsatları tek panelden takip edilir.</p></div></div><div class="flow"><span>WhatsApp</span><i>→</i><span>Ruhsat Okuma</span><i>→</i><span>Acente / Sigorta Sistemi</span><i>→</i><span>Teklif</span><i>→</i><span>Ödeme</span><i>→</i><span>Poliçe Takip</span></div></div></section>
<div class="notice">Bu sayfa entegrasyon öncesi çalışan operasyon prototipidir. Gerçek sigorta, ödeme ve poliçe sorguları; acentenin kullandığı yetkili servisler, acente yazılımı veya uygun entegrasyon altyapısı üzerinden canlı sisteme bağlanır.</div>
</div><div class="toast" id="toast"></div>
<script>
const tabs=document.querySelectorAll('.tab');function showTab(name){tabs.forEach(x=>x.classList.toggle('active',x.dataset.tab===name));['quote','monitor','overview'].forEach(n=>document.getElementById(n+'Tab').classList.toggle('hidden',n!==name));window.scrollTo({top:document.querySelector('.tabs').offsetTop-6,behavior:'smooth'})}tabs.forEach(t=>t.onclick=()=>showTab(t.dataset.tab));function goDemo(){showTab('quote');setTimeout(()=>document.getElementById('startBtn').scrollIntoView({behavior:'smooth',block:'center'}),250)}function toast(t){const x=document.getElementById('toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2200)}let running=false;document.getElementById('startBtn').onclick=async()=>{if(running)return;running=true;const c=document.getElementById('chat');c.innerHTML='<div class="msg incoming">Merhaba. Ruhsatı gönderdiğiniz anda araç bilgilerini okuyup teklif sürecini başlatabilirim.<span class="time">09:41</span></div><div class="msg outgoing">📄 ruhsat_34WAI286.jpg<span class="time">09:42</span></div>';document.getElementById('result').classList.remove('show');for(let i=1;i<=5;i++){const s=document.getElementById('s'+i);s.className='step active';await new Promise(r=>setTimeout(r,i===1?500:700));s.className='step done';if(i===2)c.innerHTML+='<div class="msg incoming">Araç bilgileri okundu: <b>34 WAI 286</b> • Renault Clio • 2023. Teklif sorgusunu başlatıyorum.<span class="time">09:42</span></div>';if(i===4){c.innerHTML+='<div class="msg incoming">Tek prim hazırlandı: <b>9.486 TL</b>. Ödeme/onay aşamasına geçebilirsiniz.<span class="time">09:43</span></div>';document.getElementById('result').classList.add('show')}}running=false};document.getElementById('payBtn').onclick=()=>toast('Demo: ödeme/onay aşamasına aktarıldı ✓');function assigned(b){b.textContent='Aktarıldı ✓';b.disabled=true;toast('Kayıt satış ekibine aktarıldı')}
</script>
</body></html>